<template>
  <div class="overview">
    <div class="section-heading"><div><h2>Tổng quan chất lượng</h2><p>Số liệu trong phạm vi kết quả bạn được phép xem.</p></div><span class="scope-note"><v-icon size="15">mdi-eye-outline</v-icon>Phạm vi: {{ workspace.runs.length.toLocaleString('vi-VN') }} lượt phân tích</span></div>
    <div class="stat-grid">
      <button v-for="metric in metrics" :key="metric.label" type="button" :class="['stat-card', { attention: metric.attention && metric.value > 0 }]" @click="emit('navigate', metric.to)">
        <span :class="['stat-icon', metric.tone]"><v-icon size="20">{{ metric.icon }}</v-icon></span>
        <span class="stat-body"><span class="stat-label">{{ metric.label }}</span><strong class="stat-value">{{ metric.value.toLocaleString('vi-VN') }}</strong><span class="stat-caption">{{ metric.caption }}</span></span>
        <v-icon size="18" class="stat-arrow">mdi-arrow-right</v-icon>
      </button>
    </div>

    <div class="middle-grid">
      <section class="qc-overview-panel activity-panel">
        <div class="panel-heading"><div><h3>Hoạt động phân tích</h3><p>7 ngày gần nhất</p></div><span class="period-count">{{ weekTotal }} lượt</span></div>
        <div class="activity-chart" role="img" :aria-label="`Số lượt phân tích 7 ngày qua: ${days.map(d => d.label + ': ' + d.value).join(', ')}`">
          <div v-for="day in days" :key="day.key" class="day-column"><span class="day-value">{{ day.value || '—' }}</span><div class="day-track"><div :class="['day-bar', { today: day.today }]" :style="{ height: day.value ? `${Math.max(8, day.value / dayMaximum * 100)}%` : '3px' }" /></div><span :class="['day-label', { 'day-label-today': day.today }]">{{ day.label }}</span></div>
        </div>
        <div class="chart-foot"><span><i /> Lượt phân tích được lưu</span><span>Hôm nay: {{ days[6]?.value ?? 0 }} lượt</span></div>
      </section>
      <section class="qc-overview-panel categories-panel">
        <div class="panel-heading"><div><h3>Nội dung cần xem xét</h3><p>Theo loại phân tích</p></div><v-icon size="20" class="muted">mdi-text-box-search-outline</v-icon></div>
        <div v-for="category in categories" :key="category.value" class="category-row"><div><span>{{ category.title }}</span><strong>{{ category.count }}</strong></div><div class="category-track"><span :style="{ width: category.count ? `${category.count / categoryMaximum * 100}%` : '0%' }" /></div></div>
        <p class="panel-note">Nhận xét của AI cần người phụ trách kiểm tra bằng chứng.</p>
      </section>
    </div>

    <div class="bottom-grid">
      <section class="qc-overview-panel recent-panel">
        <div class="panel-heading"><div><h3>Kết quả gần đây</h3><p>Cập nhật từ các lượt phân tích đã lưu</p></div><button class="text-link" @click="emit('navigate', 1)">Xem tất cả <v-icon size="16">mdi-arrow-right</v-icon></button></div>
        <v-table v-if="recent.length" class="recent-table"><thead><tr><th>Hội thoại</th><th>Thời gian</th><th>Trạng thái duyệt</th><th class="text-right">Cần xem xét</th><th /></tr></thead><tbody><tr v-for="run in recent" :key="run.id"><td><span class="conversation-label"><span class="conversation-icon"><v-icon size="17">mdi-message-text-outline</v-icon></span><span>{{ qcLabel(run.conversation.source) }}<small>{{ run.id.slice(0, 8) }}</small></span></span></td><td>{{ dateTime(run.createdAt) }}</td><td><v-chip :color="qcTone(run.reviewStatus)" size="small" variant="tonal">{{ qcLabel(run.reviewStatus) }}</v-chip></td><td class="text-right"><span :class="['finding-count', { highlighted: issues(run) > 0 }]">{{ issues(run) }}</span></td><td><v-btn icon="mdi-chevron-right" variant="text" size="small" aria-label="Xem bằng chứng phân tích" @click="emit('open', run.id)" /></td></tr></tbody></v-table>
        <div v-else class="overview-empty"><span class="empty-icon"><v-icon size="30">mdi-message-text-outline</v-icon></span><h4>Chưa có kết quả phân tích</h4><p>Chọn một hội thoại để bắt đầu kiểm tra chất lượng.</p><v-btn color="primary" variant="tonal" prepend-icon="mdi-plus" @click="emit('navigate', 1)">Phân tích hội thoại</v-btn></div>
      </section>
      <aside class="side-stack">
        <section class="qc-overview-panel readiness-panel"><div class="panel-heading"><h3>Cấu hình phân tích</h3><v-icon size="20" class="muted">mdi-cog-outline</v-icon></div>
          <div class="readiness-row"><span><v-icon size="18">mdi-robot-outline</v-icon> AI cục bộ</span><span :class="['status-pill', status?.provider.ollamaAvailable ? 'ready' : 'neutral']">{{ status?.provider.ollamaAvailable ? 'Đã cấu hình' : 'Chưa sẵn sàng' }}</span></div>
          <div class="readiness-row"><span><v-icon size="18">mdi-book-check-outline</v-icon> Quy tắc đã duyệt</span><strong>{{ approvedRules }}</strong></div>
          <div class="readiness-row"><span><v-icon size="18">mdi-timer-outline</v-icon> Lưu chứng cứ</span><strong>{{ workspace.settings.retentionDays ? `${workspace.settings.retentionDays} ngày` : 'Chưa thiết lập' }}</strong></div>
          <button class="text-link settings-link" @click="emit('navigate', 9)">Mở cài đặt <v-icon size="16">mdi-arrow-right</v-icon></button>
        </section>
        <section class="quick-panel"><span class="quick-icon"><v-icon size="22">mdi-account-group-outline</v-icon></span><h3>Giám sát theo phòng ban</h3><p>Thiết lập phạm vi, quy tắc và người phụ trách xem xét.</p><button class="text-link" @click="emit('navigate', 10)">Quản lý phòng ban <v-icon size="16">mdi-arrow-right</v-icon></button></section>
      </aside>
    </div>
    <div class="overview-footer"><v-icon size="15">mdi-information-outline</v-icon> Số lượt phân tích không đồng nghĩa với số hội thoại hoặc số nhân viên. Kết quả AI cần được đối soát.</div>
  </div>
</template>

<script setup lang="ts">
import { computed } from 'vue';
import type { QcRun, QcStatus, QcWorkspace } from '@/api/ai-quality-control';
import { analysisOptions, qcLabel, qcTone } from './presentation';
const props = defineProps<{ workspace: QcWorkspace; status: QcStatus | null }>();
const emit = defineEmits<{ navigate: [tab: number]; open: [id: string] }>();
const issues = (run: QcRun) => run.output.findings.filter(f => f.status === 'POTENTIAL_ISSUE').length;
const approvedRules = computed(() => props.workspace.documents.filter(d => d.status === 'APPROVED').length);
const metrics = computed(() => [
  { label: 'Lượt phân tích', value: props.workspace.runs.length, caption: 'Kết quả trong phạm vi hiển thị', icon: 'mdi-chart-timeline-variant', tone: 'blue', to: 1, attention: false },
  { label: 'Đang chờ duyệt', value: props.workspace.runs.filter(r => r.reviewStatus === 'PENDING').length, caption: 'Cần người phụ trách xem xét', icon: 'mdi-clock-outline', tone: 'amber', to: 8, attention: true },
  { label: 'Có nội dung cần xem xét', value: props.workspace.runs.filter(r => issues(r) > 0).length, caption: 'Lượt có nhận xét cần đối soát', icon: 'mdi-message-alert-outline', tone: 'rose', to: 1, attention: true },
  { label: 'Quy tắc đã duyệt', value: approvedRules.value, caption: 'Đang áp dụng cho phân tích', icon: 'mdi-book-check-outline', tone: 'teal', to: 5, attention: false },
]);
const recent = computed(() => [...props.workspace.runs].sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt)).slice(0, 5));
const days = computed(() => {
  const now = new Date();
  return Array.from({ length: 7 }, (_, i) => {
    const date = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 6 + i);
    const end = new Date(date.getFullYear(), date.getMonth(), date.getDate() + 1);
    return { key: date.toISOString(), label: i === 6 ? 'Hôm nay' : date.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit' }), today: i === 6,
      value: props.workspace.runs.filter(run => Date.parse(run.createdAt) >= date.getTime() && Date.parse(run.createdAt) < end.getTime()).length };
  });
});
const weekTotal = computed(() => days.value.reduce((sum, day) => sum + day.value, 0));
const dayMaximum = computed(() => Math.max(1, ...days.value.map(d => d.value)));
const categories = computed(() => analysisOptions.map(type => ({ ...type, count: props.workspace.runs.reduce((n, run) => n + run.output.findings.filter(f => f.type === type.value && f.status === 'POTENTIAL_ISSUE').length, 0) })));
const categoryMaximum = computed(() => Math.max(1, ...categories.value.map(c => c.count)));
const dateTime = (date: string) => new Date(date).toLocaleString('vi-VN', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
</script>

